# Recomputes the original paper's world poverty rates and gaps (2017 PPP data, .RData from preparation.R) by aggregating country estimates,
# as in update.R, for a like-for-like comparison. The published Table 1 computes them on the world distribution (100 percentiles), whose precision is about 1 pp.
load(".RData")
world_pop <- function(g, df = p) if (g == "now") df$pop_2022 else df$pop_2030
world_rate <- function(L, g, df = p) { r <- compute_poverty_rate(df = df, threshold = L, growth = g); pop <- world_pop(g, df); 100 * sum(r * pop, na.rm = T) / sum(pop[!is.na(r)]) }
world_gap <- function(L, g, df = p) { gp <- compute_poverty_gap(df = df, threshold = L, unit = "mean", growth = g); pop <- world_pop(g, df); 100 * sum(gp * pop, na.rm = T) / sum((df[[paste0("mean_", name_var_growth(g))]] * pop)[!is.na(gp)], na.rm = T) }
numbers <- list(PaperRatePovNow = world_rate(2.15, "now"), PaperRatePovThree = world_rate(2.15, "average"), PaperRatePovSeven = world_rate(2.15, "very_optimistic"),
                PaperRatePovSDG = world_rate(2.15, "sdg8"), PaperGapThree = world_gap(2.15, "average"))
numbers$PaperRateHundred <- numbers$PaperGapThree / 100 / tax_revenues(df = w, thresholds = 100, marginal_rates = 1, growth = "average", return = '%', scope_tax = w)
cat(paste0("% Generated by code_poverty/paper_exact.R on ", Sys.Date(), "\n"),
    sapply(names(numbers), function(n) paste0("\\newcommand{\\", n, "}{", format(round(numbers[[n]], if (numbers[[n]] < 1) 2 else 1), nsmall = if (numbers[[n]] < 1) 2 else 1), "}\n")),
    sep = "", file = "../tables/paper_exact_numbers.tex")
print(unlist(numbers))
